-- Full historical financial CORE: generated by src/build_financial_fragility.py.
-- SQL Server: verify/import the 339-row published snapshot before connecting PBIP.
USE [football_credit_risk];
GO

IF OBJECT_ID(N'dbo.financial_fragility_scores', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.financial_fragility_scores (
        club NVARCHAR(100) NOT NULL,
        fiscal_year SMALLINT NOT NULL,
        cash DECIMAL(18, 3) NOT NULL,
        current_assets DECIMAL(18, 3) NOT NULL,
        total_assets DECIMAL(18, 3) NOT NULL,
        current_liabilities DECIMAL(18, 3) NOT NULL,
        total_liabilities DECIMAL(18, 3) NOT NULL,
        equity DECIMAL(18, 3) NOT NULL,
        net_result DECIMAL(18, 3) NOT NULL,
        current_liquidity DECIMAL(18, 6) NOT NULL,
        liability_ratio DECIMAL(18, 6) NOT NULL,
        return_on_assets DECIMAL(18, 6) NOT NULL,
        negative_equity BIT NOT NULL,
        liquidity_risk DECIMAL(18, 6) NOT NULL,
        solvency_risk DECIMAL(18, 6) NOT NULL,
        profitability_risk DECIMAL(18, 6) NOT NULL,
        financial_fragility_score DECIMAL(18, 6) NOT NULL,
        previous_loss_rate DECIMAL(18, 6) NULL,
        CONSTRAINT PK_financial_fragility_scores
            PRIMARY KEY (club, fiscal_year)
    );
END;
GO

-- For a fresh rebuild on an existing local database, back up the old table,
-- then explicitly clear and reload the new table. Do not append new rows
-- to old percentile-based scores: all historical scores are recalibrated.
